const $ = (s, root = document) => root.querySelector(s);
const $$ = (s, root = document) => [...root.querySelectorAll(s)];
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const zero = value => !value || /^0x0+$/.test(value);
const short = value => value ? `${value.slice(0,6)}…${value.slice(-4)}` : 'Unknown';
const money = value => { const n = Number(value) || 0; return '$' + (n >= 1e6 ? (n / 1e6).toFixed(2) + 'M' : n >= 1000 ? (n / 1000).toFixed(2) + 'K' : n.toFixed(2)); };
const date = ts => ts && ts < 1e10 ? new Date(ts * 1000).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}) : 'Not finalized';
const clamp = (n,a,b) => Math.min(b,Math.max(a,n));
const logit = p => Math.log(clamp(p,.001,.999) / (1-clamp(p,.001,.999)));
const sigmoid = x => 1/(1+Math.exp(-x));
const chains = {1:'Ethereum',10:'OP Mainnet',100:'Gnosis',8453:'Base'};
const explorers = {1:'https://etherscan.io',10:'https://optimistic.etherscan.io',100:'https://gnosisscan.io',8453:'https://basescan.org'};
const NOW = 1792367760;
const reduced = matchMedia('(prefers-reduced-motion: reduce)');
const defaults = {state:'All',verification:'All',chain:'All',sort:'Default',direction:'Desc',conditional:false,rewards:false,futarchy:false,min:0,category:'All',kind:'All'};
let chartTab='Price', tradeSide='Buy', agentLayout='rows', consoleOpen=false, queryFormat='JSON';
let filters = {...defaults}, markets = [], agent = localStorage.getItem('seam.agent') === 'true', connected = false, collections = false, activeMarket, chosen = 0, amount = 100, range = 'All', heroIndex = 0, heroPaused = false, lastFrame = 0, holdTimer, toastTimer;
const saved = new Set(JSON.parse(localStorage.getItem('seam.saved') || '[]'));
const app = $('#app'), dialog = $('#dialog');
let visible = new Set();
const observer = new IntersectionObserver(entries => entries.forEach(e => e.isIntersecting ? visible.add(e.target) : visible.delete(e.target)),{rootMargin:'40px'});
const live = () => `<span class="live">${reduced.matches ? 'Live · motion reduced' : 'Live'} <b class="sim">SIM</b></span>`;
function rng(seed){let a=2166136261;for(const c of seed)a=Math.imul(a^c.charCodeAt(0),16777619);return()=>{a+=0x6D2B79F5;let t=a;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296;};}
function state(m){const q=m.questions || [];if(m.payoutReported)return 'Closed';if(q.some(x=>x.is_pending_arbitration))return 'In Dispute';if(NOW < Number(m.openingTs))return 'Reports not open yet';if(!m.hasAnswers || q.every(x=>zero(x.best_answer)))return 'Reports open';if(Number(m.finalizeTs)>0 && NOW >= Number(m.finalizeTs))return 'Pending execution';return 'Waiting for answer';}
function adapt(m){m.valid=m.outcomes.map((name,i)=>({name:name.trim(),i,p:m.odds?.[i]})).filter(o=>o.name!=='Invalid' && o.p!==null && o.p!==undefined);m.priced=m.valid.length>0;if(!m.priced)m.valid=m.outcomes.map((name,i)=>({name:name.trim(),i,p:null})).filter(o=>o.name!=='Invalid');m.valid.sort((a,b)=>(b.p||0)-(a.p||0));m.lead=m.valid[0] || {name:'No price',i:0,p:0};m.base=clamp(m.lead.p/100,.001,.999);m.p=m.base;m.x=logit(m.p);m.display=m.p;m.velocity=0;m.delta=0;m.random=rng(m.id);m.next=-Math.log(Math.max(m.random(),.001))/clamp(m.volumeUSD/2e5,.03,.4);m.dashes=[];m.history=Array.from({length:64},()=>clamp(m.base+(m.random()-.5)*.08,.001,.999));m.conditional=!zero(m.parentMarket?.id);m.futarchy=/futarchy/i.test(m.type)||!zero(m.collateralToken1);m.scalar=Number(m.upperBound)!==0 || Number(m.lowerBound)!==0;m.kind=m.scalar ? (m.templateId==='6'?'Multi Scalar':'Scalar') : m.valid.length>2?'Multi Categorical':'Categorical';m.status=state(m);m.fresh=m.random()<.65?'Fresh':m.random()<.65?'Cooling':'Stale';return m;}
function pFor(m,index){const o=m.valid.find(o=>o.i===index);if(!o)return 0;if(index===m.lead.i)return m.p;return clamp(o.p/100*(1-m.p)/(1-m.base),0,1);}
function signal(m){const L=Math.max(m.liquidityUSD,50),c5=.25*L*Math.abs(logit(Math.min(m.p+.05,.99))-logit(m.p));let tier=c5<100?0:c5<1000?1:c5<10000?2:3;const sum=m.valid.reduce((s,o)=>s+o.p,0);if(m.volumeUSD<m.liquidityUSD)tier--;if(Math.abs(sum-100)>3)tier--;return {market:m.id,chain:m.chainId,question:m.marketName,p_yes:m.priced?+m.p.toFixed(4):null,confidence:m.priced?['Thin','Fair','Solid','Deep'][Math.max(0,tier)]:'Unavailable',cost_to_move_5pt_usd:m.priced?Math.round(c5):null,stale:m.fresh.toLowerCase(),resolves_after:m.finalizeTs<1e10?new Date(m.finalizeTs*1000).toISOString():null,oracle:'reality.eth',arbitrator:m.questions?.[0]?.arbitrator?.startsWith('0x6815')?'kleros':m.questions?.[0]?.arbitrator||null,min_bond_xdai:Number(m.questions?.[0]?.min_bond||0)/1e18,conditional_on:m.conditional?{market:m.parentMarket.id,outcome:m.parentOutcome}:null};}
function verification(m){return {verified:'✓',verifying:'◌',challenged:'!',not_verified:'△'}[m.verification?.status]||'△';}
function countdown(m){const d=(Number(m.openingTs)-NOW)/86400;return d>0?`${Math.floor(d)}d ${Math.floor((d%1)*24)}h` : m.status;}
function how(m){if(!m.priced)return 'No pool-implied price is available. The market has no priced outcome in this sample.';const s=signal(m);return `${m.lead.name} costs ${money(m.p)} per share and pays $1.00 if it wins. ${s.confidence}: about ${money(s.cost_to_move_5pt_usd)} moves it 5 points.${m.fresh==='Stale'?' Price may be outdated; last trade 3 days ago (SIM).':''}`;}
function parentName(m){return markets.find(x=>x.id===m.parentMarket?.id)?.marketName || short(m.parentMarket?.id);}
function canvas(m,cls='seam'){return `<canvas class="${cls}" data-market="${m.id}" aria-label="${esc(m.lead.name)} ${m.lead.p}% price seam"></canvas>`;}
function buyButtons(m){return `<div class="buys">${m.valid.slice(0,2).map((o,i)=>`<button class="${i===0?'primary':'secondary'}" data-action="quick" data-id="${m.id}" data-index="${o.i}" ${o.p===null?'disabled':''}>${esc(m.scalar?(i===0?'Up':'Down'):o.name)} ${o.p===null?'Unavailable':Number(o.p).toFixed(0)+'¢'}</button>`).join('')}</div>`;}
function category(m){const text=(m.categories||[]).join(' ').toLowerCase();return /politic/.test(text)?'Politics':/crypto/.test(text)?'Crypto':/sport/.test(text)?'Sports':/science/.test(text)?'Science':/tech/.test(text)?'Tech':/financ/.test(text)?'Finance':/seer|reality|kleros/i.test(m.marketName)?'Markets about Seer/Reality/Kleros':'Culture';}
function statusLabel(m){return m.status==='Closed'?'Closed':m.status==='In Dispute'?'In dispute':m.status==='Reports not open yet'?'Open':'Answering';}
function kindLabel(m){return m.scalar?(m.templateId==='6'?'Multi-scalar':'Scalar'):m.templateId==='3'?'Multi-categorical':m.valid.length===2?'Binary':'Categorical';}
function spark(m,cls='spark'){return `<svg class="${cls}" viewBox="0 0 320 100" preserveAspectRatio="none" role="img" aria-label="Simulated price history"><path d="${m.history.map((p,i)=>`${i?'L':'M'}${i*320/63},${100-p*100}`).join(' ')}"/></svg>`;}
function card(m,i){return `<article class="market-card" data-id="${m.id}" style="--delay:${Math.min(i,15)*20}ms"><a class="card-link" href="#/market/${m.id}" aria-label="${esc(m.marketName)}"></a><div class="tile-meta"><span class="category">${esc(category(m))}</span><span class="status-word">● ${statusLabel(m)}</span><span aria-label="${esc(m.verification?.status)}">${verification(m)}</span></div><h2 class="question">${esc(m.marketName)}</h2>${m.conditional?`<p class="tile-condition">If ${+m.parentOutcome===0?'Yes':'No'}: ${esc(parentName(m))}</p>`:''}<div class="tile-outcomes">${m.valid.slice(0,2).map(o=>`<div class="tile-outcome"><span>${esc(o.name)}</span><strong ${o.i===m.lead.i?`data-cents="${m.id}"`:''}>${o.p===null?'Unavailable':Number(o.p).toFixed(1)+'¢'}</strong><div class="probability"><i style="width:${clamp(o.p||0,0,100)}%"></i></div></div>`).join('')}</div>${m.scalar?`<div class="range-dial"><span>${esc(m.lowerBound)}</span><meter min="0" max="100" value="${m.p*100}" aria-label="Scalar range estimate"></meter><span>${esc(m.upperBound)}</span></div>`:m.valid.length>2?`<a class="more-outcomes" href="#/market/${m.id}">+${m.valid.length-2} more outcomes</a>`:''}<div class="card-foot"><span>${money(m.volumeUSD)} vol</span><span>${money(m.liquidityUSD)} liq</span><span>${Number(m.openingTs)>NOW?'Closes in '+countdown(m):'Answers open'}</span><button data-action="star" data-id="${m.id}" class="${saved.has(m.id)?'saved':''}" aria-label="${saved.has(m.id)?'Remove saved market':'Save market'}">${saved.has(m.id)?'★':'☆'}</button></div>${agent?machineStrip(m):''}<div class="tile-actions">${buyButtons(m)}<button class="touch-trade" data-action="quick" data-id="${m.id}" data-index="${m.lead.i}">Trade ›</button></div><div class="drawer"><p>Asked by <a href="${explorers[m.chainId]}/address/${m.creator}" target="_blank" rel="noreferrer">${short(m.creator)}</a></p><p>Resolution source <a href="https://reality.eth.limo/app/#!/question/${m.chainId}-${m.questions?.[0]?.id}" target="_blank" rel="noreferrer">Reality.eth ↗</a></p><div class="peek-chart">${canvas(m,'peek-history')}<span>7d history · SIM</span></div><p>Depth / liquidity <button data-action="pools" data-id="${m.id}">${money(m.liquidityUSD)} ↗</button></p><p>Last trade / traders <span>Not in sample</span></p><p class="read-line">How to read it: ${m.priced?`${(m.p*100).toFixed(1)}% means traders price ${esc(m.lead.name)} at ${(m.p*100).toFixed(1)} cents per share.`:'No pool price is available.'}</p></div></article>`;}

function agentLine(m){const s=signal(m);return `p ${m.priced?m.p.toFixed(3):'Unavailable'} · ${s.confidence.toLowerCase()} · c5 ${money(s.cost_to_move_5pt_usd)} · ${s.stale}`;}
function matches(m,f=filters){return (f.category==='All'||category(m)===f.category)&&(f.kind==='All'||f.kind.split('|').includes(kindLabel(m)))&&(f.state==='All'||f.state.split('|').includes(statusLabel(m)))&&(f.verification==='All'||f.verification.split('|').includes(m.verification?.status==='verified'?'Verified':'Unverified'))&&(f.chain==='All'||f.chain.split('|').includes(String(m.chainId)))&&(!f.conditional||m.conditional)&&(!f.rewards||m.incentive>0)&&(!f.futarchy||m.futarchy)&&m.liquidityUSD>=Number(f.min);}
function selectedMarkets(){const q=$('#search').value.toLowerCase();let list=markets.filter(m=>matches(m)&&(!collections||saved.has(m.id))&&`${m.marketName} ${m.outcomes.join(' ')} ${m.id}`.toLowerCase().includes(q));const key={Liquidity:'liquidityUSD',Volume:'volumeUSD','Open Interest':'openInterestUSD','Opening Date':'openingTs','Creation Date':'blockTimestamp',Newest:'blockTimestamp',Trending:'volumeUSD','Ending soon':'openingTs'}[filters.sort];if(key)list.sort((a,b)=>(Number(a[key])-Number(b[key]))*(filters.direction==='Asc'?1:-1));return list;}
function viewToggle(){return `<div class="view-toggle ${agent?'is-agent':''}" role="group" aria-label="Explorer mode"><i aria-hidden="true"></i><button data-action="human" class="${!agent?'selected':''}">Human</button><button data-action="agent" class="agent ${agent?'selected':''}">Agent</button></div>`;}
function home(){activeMarket=null;observer.disconnect();visible.clear();app.innerHTML=`<section class="stats" aria-label="Protocol sample statistics">${[['Markets',markets.length],['Total volume',money(markets.reduce((n,m)=>n+m.volumeUSD,0))],['24h volume','Not in sample'],['Active traders','Not in sample'],['Open disputes',markets.filter(m=>statusLabel(m)==='In dispute').length]].map(([k,v])=>`<div><span>${k}</span><strong>${v}</strong></div>`).join('')}</section><section id="hero" class="trending-module" tabindex="0" aria-label="Trending now carousel"></section><section class="board"><div class="toolbar"><h1>All markets</h1><span class="count" id="result-count"></span>${live()}${viewToggle()}<button class="secondary" data-action="collections">${collections?'All markets':'My collections'}</button></div><div class="filter-bar"><div class="categories">${['All','Politics','Crypto','Sports','Culture','Tech','Science','Finance','Markets about Seer/Reality/Kleros'].map(c=>`<button data-action="category" data-value="${c}" class="${filters.category===c?'selected':''}">${c}</button>`).join('')}</div><div class="filter-pills">${[['state','Status'],['verification','Verification'],['chain','Chain'],['kind','Type'],['sort','Sort']].map(([k,label])=>`<div class="filter-anchor"><button data-action="filter-popover" data-key="${k}" aria-expanded="false">${label}<span data-filter-count="${k}"></span> ⌄</button></div>`).join('')}</div></div><div id="tags" class="tags"></div><div id="grid" class="grid"></div><div class="end">End of sample · ${markets.length} real Seer markets</div></section>`;renderHero();renderGrid();}

function renderGrid(){if(!$('#grid'))return;observer.disconnect();visible.clear();const list=selectedMarkets();$('#result-count').textContent=`${markets.length} → ${list.length} markets`;$('#grid').innerHTML=list.length?list.map(card).join(''):`<div class="empty" style="grid-column:1/-1">No matching markets <button data-action="reset">Clear filters</button></div>`;$('#tags').innerHTML=Object.entries(filters).filter(([k,v])=>v!==defaults[k]).map(([k,v])=>`<button class="tag" data-action="remove-filter" data-key="${k}">${esc(k==='min'?`Liquidity ≥ ${money(v)}`:v===true?k:v)} ×</button>`).join('');if($('#tags').children.length)$('#tags').insertAdjacentHTML('beforeend','<button data-action="reset">Clear all</button>');$$('[data-filter-count]').forEach(el=>{const v=filters[el.dataset.filterCount];el.textContent=v!==defaults[el.dataset.filterCount]?' ('+v.split('|').length+')':'';});$$('[data-action=category]').forEach(b=>b.classList.toggle('selected',b.dataset.value===filters.category));registerCanvases();syncAgent();}
const trending=()=>[...markets].sort((a,b)=>b.volumeUSD-a.volumeUSD).slice(0,5);
function renderHero(){const host=$('#hero');if(!host)return;const list=trending(),m=list[heroIndex];host.innerHTML=`<div class="trending-heading"><h2>Trending now</h2><div><button data-action="hero" data-index="${(heroIndex+4)%5}" aria-label="Previous featured market">‹</button><button data-action="hero" data-index="${(heroIndex+1)%5}" aria-label="Next featured market">›</button></div></div><div class="trending-columns"><section class="featured"><div class="eyebrow">Asked on Reality.eth · ${esc(category(m))}</div><a href="#/market/${m.id}"><h3>${esc(m.marketName)}</h3></a><div class="featured-price"><span>${esc(m.lead.name)}</span><strong data-price="${m.id}">${m.priced?(m.p*100).toFixed(1)+'%':'Unavailable'}</strong><span>24h change: unavailable</span></div>${canvas(m,'featured-chart history')}<div class="chart-note"><span>Simulated price history</span><b class="sim">SIM</b></div><div class="featured-facts"><span>Volume <b>${money(m.volumeUSD)}</b></span><span>Liquidity <b>${money(m.liquidityUSD)}</b></span><span>Resolution <b>${date(m.finalizeTs)}</b></span></div><div class="featured-actions"><button class="primary" data-action="quick" data-id="${m.id}" data-index="${m.lead.i}" ${m.priced?'':'disabled'}>Trade</button><a href="#/market/${m.id}">View market ↗</a>${live()}</div><div class="progress-segments">${list.map((_,i)=>`<button data-action="hero" data-index="${i}" class="${i===heroIndex?'selected':''}" aria-label="Feature market ${i+1}"><i></i></button>`).join('')}</div></section><section class="most-traded"><div class="list-heading"><h2>Most traded today</h2><a href="#all-markets" data-action="view-all">View all ↓</a></div><p class="sample-note">Ranked by sample total volume; daily data unavailable</p>${list.map((x,i)=>`<button class="ranked-row ${i===heroIndex?'selected':''}" data-action="hero" data-index="${i}"><span class="rank">${i+1}</span><span class="rank-question">${esc(x.marketName)}</span><strong>${x.priced?(x.p*100).toFixed(1)+'¢':'No price'}</strong><span class="rank-change">24h: N/A</span>${spark(x)}</button>`).join('')}</section></div>`;registerCanvases();host.onpointerenter=()=>{heroPaused=true;host.classList.add('paused');};host.onpointerleave=()=>{heroPaused=false;host.classList.remove('paused');};host.onfocusin=()=>heroPaused=true;host.onfocusout=e=>{if(!host.contains(e.relatedTarget))heroPaused=false;};host.onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();heroIndex=(heroIndex+(e.key==='ArrowRight'?1:4))%5;renderHero();host.focus();}};}

function writeURL(){const u=new URL(location);Object.entries(filters).forEach(([k,v])=>v!==defaults[k]?u.searchParams.set(k,v):u.searchParams.delete(k));$('#search').value?u.searchParams.set('marketName',$('#search').value):u.searchParams.delete('marketName');history.replaceState(null,'',u);}
function readURL(){const p=new URLSearchParams(location.search);for(const k of Object.keys(defaults)){if(p.has(k))filters[k]=typeof defaults[k]==='boolean'?p.get(k)==='true':k==='min'?Math.max(0,Number(p.get(k))||0):p.get(k);}$('#search').value=p.get('marketName')||'';}
function closePopover(){$$('.filter-popover,.app-popover,.recent-searches').forEach(p=>p.remove());$$('[aria-expanded=true]').forEach(b=>b.setAttribute('aria-expanded','false'));}
function openFilters(key,button){const already=button.getAttribute('aria-expanded')==='true';closePopover();if(already)return;const options={state:['Open','Answering','In dispute','Closed'],verification:['Verified','Unverified'],chain:Object.keys(chains),kind:['Binary','Categorical','Multi-categorical','Scalar','Multi-scalar'],sort:['Trending','Newest','Volume','Liquidity','Ending soon']}[key];const pop=document.createElement('div');pop.className='filter-popover';pop.setAttribute('aria-label',key+' options');pop.innerHTML=options.map(v=>`<label><input type="checkbox" value="${v}" ${filters[key].split('|').includes(v)?'checked':''}><span>${chains[v]||v}</span><span>${markets.filter(m=>matches(m,{...defaults,[key]:v})).length}</span></label>`).join('');pop.style.setProperty('--popover-top',button.getBoundingClientRect().bottom+8+'px');button.parentElement.append(pop);button.setAttribute('aria-expanded','true');pop.onchange=e=>{const values=$$('input:checked',pop).map(x=>x.value);if(key==='sort'){filters[key]=e.target.checked?e.target.value:defaults[key];$$('input',pop).forEach(x=>x.checked=x.value===filters[key]);}else filters[key]=values.join('|')||'All';writeURL();renderGrid();};}
function openApps(button){const already=$('.app-popover');closePopover();if(already)return;const pop=document.createElement('div');pop.className='app-popover';pop.innerHTML=[['Seer App','../explorer/'],['Deep','../deep/'],['Futarchy','../futarchy/'],['Opportunity Markets','../opportunity/'],['Risk Pricing','https://foresight.kleros.io'],['Explorer','../explorer/']].map(([name,url],i)=>`<a href="${url}" target="_blank" rel="noreferrer" ${name==='Explorer'?'aria-current="page"':''}><span class="product-glyph" style="--phase:${i*90}ms">${['▱','⋮','⑂','≋','◔','⌕'][i]}</span>${name}${name==='Explorer'?'<small>Current</small>':'<span>↗</span>'}</a>`).join('');button.parentElement.append(pop);button.setAttribute('aria-expanded','true');}

function showDialog(title,body){$('#dialog-body').innerHTML=`<button class="close" data-action="close-dialog" aria-label="Close dialog">×</button><h2>${title}</h2>${body}`;if(!dialog.open)dialog.showModal();}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function connect(){if(connected){showDialog('Account',`<p><code>0x0000…dEaD</code> · 24.69 xDAI · 0 sDAI</p><div class="menu-list">${['Deposit','Portfolio','Market Collections','Trade Collateral'].map(s=>`<button data-action="account-item" data-label="${s}">${s}</button>`).join('')}<label class="filter-option"><input type="checkbox">Use smart account</label><button data-action="disconnect">Disconnect</button></div>`);return;}connected=true;$('#wallet').textContent='0x0000…dEaD';toast('Mock wallet connected · 24.69 xDAI · 0 sDAI');updateQuote();if($('#quick-cta'))updateQuick();}
let quickMarket,quickIndex=0;
function quick(m,index){quickMarket=m;quickIndex=index;showDialog('Quick buy · estimate',`<div class="segmented">${m.valid.slice(0,2).map(o=>`<button data-action="quick-side" data-index="${o.i}" class="${o.i===index?'selected':''}">${esc(o.name)}</button>`).join('')}</div><label for="quick-amount">You pay · ${collateral(m)} · Balance 0</label><input class="quick-amount" id="quick-amount" type="number" min="0" step="any" value="100" inputmode="decimal"><div class="quick-pay" id="quick-pay"></div><button id="quick-cta" class="primary" data-action="quick-confirm">Connect</button>`);$('#quick-amount').oninput=updateQuick;updateQuick();}
function collateral(m){if(!m.conditional)return 'sDAI';const parent=markets.find(x=>x.id===m.parentMarket.id);return parent?.poolBalance?.[+m.parentOutcome]?.token0?.symbol||`Parent ${+m.parentOutcome===0?'Yes':'No'} token`;}
// Logit impact is an illustrative depth model, not an executable pool quote.
function quote(m,index,a){const p=clamp(pFor(m,index),.001,.999),after=sigmoid(logit(p)+a/(.25*Math.max(m.liquidityUSD,50))),avg=(p+after)/2;return {p,after,avg,shares:a/avg,ret:(1/avg-1)*100};}
function cta(a){return !connected?'Connect':a<=0?'Enter an amount':'Not enough balance.';}
function updateQuick(){if(!$('#quick-amount'))return;const a=Math.max(0,Number($('#quick-amount').value)||0),q=quote(quickMarket,quickIndex,a);$('#quick-pay').textContent=`Pays ${q.shares.toFixed(2)} ${collateral(quickMarket)} if ${quickMarket.outcomes[quickIndex]} wins`;$('#quick-cta').textContent=cta(a);}
function brief(m){const q=m.questions?.[0]||{},arb=q.arbitrator?.startsWith('0x6815')?'Kleros':`Unknown arbitrator ${short(q.arbitrator)}`,s=signal(m);return `<div class="brief"><section><h3>WHO IS ASKING</h3><p>Asked by <a href="${explorers[m.chainId]}/address/${m.creator}" target="_blank" rel="noreferrer">${short(m.creator)}</a> on ${date(m.blockTimestamp)}. Answered through Reality.eth; disputes go to ${esc(arb)}. A wrong answer risks at least ${s.min_bond_xdai} xDAI (now ${Number(q.bond||0)/1e18}). ${m.verification?.status==='verified'?'Kleros curators verified this market.':`Verification: ${esc(m.verification?.status||'not_verified')}.`}</p></section><section><h3>WHAT IS PRICED</h3><p>${m.scalar?`Pays along a scale from ${m.lowerBound} to ${m.upperBound}; today's estimate is ${m.priced?(Number(m.lowerBound)+m.p*(Number(m.upperBound)-Number(m.lowerBound))).toFixed(2):'unavailable'}.`:`Resolves to the final Reality.eth answer. A winning ${esc(m.lead.name)} share pays 1 ${collateral(m)}.`} Answers opened ${date(m.openingTs)}; earliest final answer: ${date(m.finalizeTs)}. The challenge window is ${Number(q.timeout||0)/86400} days.${m.outcomes.includes('Invalid')?' Invalid pays if the question is ruled invalid.':''}</p></section><section><h3>HOW TO USE THE SIGNAL</h3><p>${esc(how(m))} ${m.conditional?`Only pays if ${esc(parentName(m))} resolves ${+m.parentOutcome===0?'Yes':'No'}.`:''} <b class="sim">SIM</b> ${m.fresh.toLowerCase()} last trade.</p></section></div>`;}
function marketPage(m){
 activeMarket=m;chosen=m.lead.i;amount=100;tradeSide='Buy';chartTab='Price';observer.disconnect();visible.clear();
 app.innerHTML=`<div class="breadcrumb"><a href="#/">Home</a><span>/</span><a href="#/">Markets</a><span>/ Market</span>${viewToggle()}</div>
 ${m.conditional?`<div class="banner">Conditional on <a href="#/market/${m.parentMarket.id}">${esc(parentName(m))}</a> being ${+m.parentOutcome===0?'Yes':'No'}.</div>`:''}
 <div class="market-heading"><h1>${esc(m.marketName)}</h1></div><div class="market-meta">${[kindLabel(m),m.verification?.status||'Unverified',chains[m.chainId]||m.chainId,Number(m.openingTs)>NOW?'Closes in '+countdown(m):m.status].map(x=>`<span class="category">${esc(x)}</span>`).join('')}${live()}</div>
 <div class="market-actions"><button data-action="share">Share</button><button data-action="star" data-id="${m.id}" aria-label="Save market">${saved.has(m.id)?'★':'☆'}</button><a class="secondary" href="https://reality.eth.limo/app/#!/question/${m.chainId}-${m.questions?.[0]?.id}" target="_blank" rel="noreferrer">Answer on Reality.eth ↗</a></div>
 <div class="market-layout terminal"><div class="terminal-main"><section class="panel"><div class="tabs chart-tabs">${['Price','Depth','Volume','Traders'].map(t=>`<button data-action="chart-tab" data-tab="${t}" class="${t==='Price'?'selected':''}">${t}</button>`).join('')}<button data-action="export" aria-label="Export price history">↓ CSV</button></div><div class="chart-tools">${['1D','1W','1M','All'].map(r=>`<button data-action="range" data-range="${r}" class="${r===range?'selected':''}">${r}</button>`).join('')}</div><div id="chart-stage"></div><div class="outcome-legend">${m.valid.slice(0,3).map(o=>`<span>${esc(o.name)} <b ${o.i===m.lead.i?`data-cents="${m.id}"`:''}>${o.p===null?'Unavailable':o.p.toFixed(1)+'¢'}</b></span>`).join('')}</div></section>
 <section class="panel"><div class="tabs detail-tabs">${['About','Outcomes','Activity','Holders','Dispute and Resolution'].map(t=>`<button data-action="tab" data-tab="${t}" class="${t==='About'?'selected':''}">${t}</button>`).join('')}</div><div id="tab-content" class="tab-content"></div></section>
 <section class="rope-panel"><div class="rope-labels"><h2>Fair depth</h2><span>Price impact: 5 points per ${money(signal(m).cost_to_move_5pt_usd)}</span></div>${canvas(m,'rope')}<p class="muted">Estimated depth · SIM</p></section></div>${ticket(m)}</div>
 <section class="panel related"><h2>Related markets</h2>${markets.filter(x=>x.id!==m.id&&category(x)===category(m)).slice(0,3).map(x=>`<a href="#/market/${x.id}"><span>${esc(x.marketName)}</span><strong>${x.priced?(x.p*100).toFixed(1)+'¢':'Unavailable'}</strong></a>`).join('')||'<p>No related markets in sample.</p>'}</section><button class="mobile-trade primary" data-action="trade">Trade ↗</button>`;
 renderTab('About');renderChart();registerCanvases();bindTicket();updateQuote();syncAgent();
}
function renderChart(){const m=activeMarket,host=$('#chart-stage');if(!host)return;
 if(chartTab==='Price'){host.innerHTML=`<canvas class="history" data-market="${m.id}" tabindex="0" aria-label="Simulated price history, 0 to 100 percent. Arrow keys inspect points."></canvas><div class="chart-note">Pool-implied price · simulated history · ${range}</div>`;bindHistory();}
 else if(chartTab==='Depth')host.innerHTML=`${canvas(m,'rope')}<div class="chart-note">Estimated depth · ${money(m.liquidityUSD)} liquidity · ${range}</div>${m.valid.slice(0,4).map(o=>`<div class="pool-row">${esc(o.name)}: ${money(.25*Math.max(m.liquidityUSD,50)*Math.abs(logit(clamp(pFor(m,o.i)+.01,.001,.999))-logit(clamp(pFor(m,o.i),.001,.999))))} to move 1 point · SIM</div>`).join('')}`;
 else host.innerHTML=`<div class="chart-unavailable"><h2>${chartTab}</h2><p>${chartTab==='Volume'?'Total volume '+money(m.volumeUSD)+'. Historical volume':'Trader history'} is not included in this sample.</p><span>Range: ${range}</span></div>`;
 registerCanvases();
}
function outcomes(m,all=false){return m.valid.slice(0,all?100:8).map(o=>`<div class="outcome ${o.i===chosen?'selected':''}"><button data-action="outcome" data-index="${o.i}">${esc(o.name)}</button><strong>${o.p===null?'Unavailable':o.p.toFixed(1)+'%'}</strong><button class="icon" data-action="outcome-menu" data-index="${o.i}" aria-label="Actions for ${esc(o.name)}">⋯</button></div>`).join('');}
function ticket(m){return `<aside class="ticket panel" id="ticket"><div class="ticket-head"><h2>Trade</h2><button class="icon" data-action="close-trade" aria-label="Close trade ticket">×</button></div><div class="segmented trade-side"><button class="selected" data-action="trade-side" data-side="Buy">Buy</button><button data-action="trade-side" data-side="Sell">Sell</button></div><label class="amount-label" for="outcome-select">Outcome</label><select id="outcome-select">${m.valid.map(o=>`<option value="${o.i}" ${o.i===chosen?'selected':''}>${esc(o.name)}</option>`).join('')}</select><div class="segmented" id="ticket-sides">${m.valid.slice(0,2).map(o=>`<button data-action="outcome" data-index="${o.i}" class="${o.i===chosen?'selected':''}">${esc(o.name)} ${o.p===null?'Unavailable':o.p.toFixed(0)+'¢'}</button>`).join('')}</div>${canvas(m,'mini-rope')}<input id="target-price" type="range" aria-label="Drag target price to set amount" min="0" max="1000" value="0"><div class="amount-label"><span>You pay · ${collateral(m)}</span><span>Balance 0 <button data-action="max" style="height:24px;padding:0 8px;font-size:12px">Max</button></span></div><div class="amount-wrap"><span>$</span><input id="amount" aria-label="You pay amount" type="number" inputmode="decimal" min="0" step="any" value="100"><span>${collateral(m)}</span></div><div id="quote-line" class="quote-line"></div><div class="payoff"><div class="payoff-row"><span id="payoff-label"></span><strong id="payoff-value"></strong></div><div class="payoff-bar"><i id="payoff-width"></i></div><div class="payoff-row"><span>Otherwise</span><strong>0.00</strong></div></div><div class="ticket-tools"><button data-action="order-type">Market⌄</button><button data-action="slippage">Max slippage 1% ⚙</button><button data-action="more">More⌄</button><span class="sim">Estimate</span></div><button id="trade-cta" class="primary trade-cta" data-action="trade-confirm">Connect</button><button class="bridge" data-action="bridge" style="background:none;height:auto;padding:0">Low balance? Bridge tokens from other networks ↗</button></aside>`;}
function bindTicket(){$('#outcome-select').onchange=e=>{chosen=Number(e.target.value);updateQuote();};const mini=$('.mini-rope');let dragging=false;const drag=e=>{if(!dragging||!activeMarket.priced)return;const rect=mini.getBoundingClientRect(),p=clamp(pFor(activeMarket,chosen),.001,.999),target=clamp((e.clientX-rect.left)/rect.width,p,.999);amount=Math.max(0,.25*Math.max(activeMarket.liquidityUSD,50)*(logit(target)-logit(p)));$('#amount').value=amount.toFixed(2);updateQuote();};mini.onpointerdown=e=>{dragging=true;mini.setPointerCapture(e.pointerId);drag(e);};mini.onpointermove=drag;mini.onpointerup=mini.onpointercancel=()=>dragging=false;$('#amount').oninput=()=>{amount=Math.max(0,Number($('#amount').value)||0);updateQuote();};$('#target-price').oninput=()=>{const p=clamp(pFor(activeMarket,chosen),.001,.999);const target=p+( .999-p)*Number($('#target-price').value)/1000;amount=Math.max(0,.25*Math.max(activeMarket.liquidityUSD,50)*(logit(target)-logit(p)));$('#amount').value=amount.toFixed(2);updateQuote(false);};const c=$('#trade-cta');c.onpointerdown=()=>{if(!connected||amount<=0)return;const start=performance.now();holdTimer=setInterval(()=>{const t=(performance.now()-start)/600;c.style.setProperty('--hold',Math.min(t,1));if(t>=1){clearInterval(holdTimer);c.style.setProperty('--hold',0);toast('Not enough balance. · Prototype: signing disabled');}},16);};c.onpointerup=c.onpointerleave=c.onpointercancel=()=>{clearInterval(holdTimer);c.style.setProperty('--hold',0);};c.onkeydown=e=>{if(e.key==='Enter'&&connected&&amount>0){e.preventDefault();showDialog('Confirm estimate',`<p>${amount.toFixed(2)} ${collateral(activeMarket)} → ${quote(activeMarket,chosen,amount).shares.toFixed(2)} shares</p><button class="primary" data-action="reject">Confirm</button>`);}};}
function updateQuote(updateSlider=true){if(!activeMarket||!$('#quote-line'))return;if(!activeMarket.priced){$('#quote-line').textContent='No pool price available';$('#payoff-label').textContent='Payout estimate unavailable';$('#payoff-value').textContent='Unavailable';$('#payoff-width').style.width='0%';$('#trade-cta').textContent='No pool price available';$('#trade-cta').disabled=true;$('#target-price').disabled=true;$('#amount').disabled=true;return;}const q=quote(activeMarket,chosen,amount);if(tradeSide==='Sell'){const proceeds=amount*q.p;$('#quote-line').innerHTML=`Sell ${amount.toFixed(4)} shares · avg ${(q.p*100).toFixed(1)}¢<br>Estimated proceeds ${proceeds.toFixed(4)} ${collateral(activeMarket)}<br>Price impact unavailable · Fees unavailable`;$('#payoff-label').textContent='You receive, before fees';$('#payoff-value').textContent=proceeds.toFixed(4);$('#payoff-width').style.width='0%';$('#trade-cta').textContent=connected?'Not enough share balance.':'Connect';return;}$('#quote-line').innerHTML=`Moves price <b>${(q.p*100).toFixed(1)} → ${(q.after*100).toFixed(1)}</b> · avg ${(q.avg*100).toFixed(1)}¢<br>You will get <strong>${q.shares.toFixed(4)} shares</strong><br>Price impact ${((q.after-q.p)*100).toFixed(2)} points · Fees unavailable`;$('#payoff-label').textContent=`If ${activeMarket.outcomes[chosen]} wins`;$('#payoff-value').textContent=`${q.shares.toFixed(2)} (+${q.ret.toFixed(1)}%)`;$('#payoff-width').style.width=`${clamp(q.ret,4,100)}%`;$('#trade-cta').textContent=cta(amount);if(updateSlider)$('#target-price').value=1000*(q.after-q.p)/(.999-q.p);}
function renderTab(tab){const host=$('#tab-content'),m=activeMarket;if(!host)return;$$('.detail-tabs button').forEach(b=>b.classList.toggle('selected',b.dataset.tab===tab));
 if(tab==='About')host.innerHTML=`<h2>Information</h2>${brief(m)}<h2 class="timeline-title">Resolution timeline</h2><p>Created ${date(m.blockTimestamp)} · Answers open ${date(m.openingTs)} · Final answer ${date(m.finalizeTs)}</p>`;
 else if(tab==='Outcomes')host.innerHTML=`<div class="data-table"><table><thead><tr><th>Outcome</th><th>Price</th><th>24h change</th><th>Volume</th><th>Liquidity</th></tr></thead><tbody>${m.valid.map(o=>`<tr><td><button data-action="outcome" data-index="${o.i}">${esc(o.name)}</button></td><td>${o.p===null?'Unavailable':o.p.toFixed(1)+'¢'}</td><td>N/A</td><td>N/A</td><td>N/A</td></tr>`).join('')}</tbody></table></div><p>Per-outcome volume, liquidity and daily changes unavailable.</p>`;
 else if(tab==='Dispute and Resolution'){const q=m.questions?.[0]||{};host.innerHTML=`<ol class="resolution-steps">${[['Reality.eth answer',zero(q.best_answer)?'Not answered yet':q.best_answer],['Bond',Number(q.bond||0)/1e18+' xDAI, minimum '+Number(q.min_bond||0)/1e18+' xDAI'],['Challenge window',Number(q.timeout||0)/86400+' days'],['Kleros status',q.is_pending_arbitration?'In dispute':'No pending arbitration']].map(([k,v],i)=>`<li><b>${i+1}. ${k}</b><span>${esc(v)}</span></li>`).join('')}</ol><button data-action="answer">Answer on Reality.eth</button>`;}
 else host.textContent=tab==='Activity'?'Recent trade records are not included in this sample.':'Holder records are not included in this sample.';
}
function registerCanvases(){$$('canvas[data-market]',app).forEach(c=>observer.observe(c));}
function draw(c,m,time,dt){const rect=c.getBoundingClientRect();if(rect.width===0)return;const dpr=Math.min(devicePixelRatio||1,2),w=rect.width,h=rect.height;if(c.width!==Math.round(w*dpr)||c.height!==Math.round(h*dpr)){c.width=Math.round(w*dpr);c.height=Math.round(h*dpr);}const ctx=c.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);if(!m.priced){ctx.fillStyle=getComputedStyle(c).getPropertyValue('--text-2');ctx.font='12px system-ui';ctx.fillText(c.classList.contains('history')?'No price history in sample':'No pool price',8,h/2+4);return;}const style=getComputedStyle(c),color=n=>style.getPropertyValue(n).trim(),violet=color('--violet'),ink=color('--text-2'),bg=color('--card'),text=color('--text-2');if(c.classList.contains('history')||c.classList.contains('peek-history')){drawHistory(ctx,m,w,h,color);return;}const rope=c.classList.contains('rope'),mini=c.classList.contains('mini-rope'),p=m.display,x=clamp(p*w,2,w-2),y=h/2-(rope?8:0);ctx.save();if(rope){ctx.beginPath();for(let i=0;i<=w;i+=2){const u=clamp(i/w,.01,.99),height=clamp(10*.25/(u*(1-u)),8,40);i?ctx.lineTo(i,y-height):ctx.moveTo(i,y-height);}for(let i=w;i>=0;i-=2){const u=clamp(i/w,.01,.99);ctx.lineTo(i,y+clamp(10*.25/(u*(1-u)),8,40));}ctx.closePath();ctx.clip();}else{ctx.beginPath();ctx.rect(0,y-4,w,8);ctx.clip();}ctx.fillStyle=violet;ctx.fillRect(0,0,x,h);ctx.fillStyle=color('--nested');ctx.fillRect(x,0,w-x,h);ctx.strokeStyle=ink;ctx.globalAlpha=.5;ctx.lineWidth=1;for(let i=x-h;i<w+h;i+=4){ctx.beginPath();ctx.moveTo(i,0);ctx.lineTo(i+h,h);ctx.stroke();}ctx.globalAlpha=1;ctx.restore();ctx.fillStyle=bg;ctx.fillRect(x-2,y-(rope?48:8),4,rope?96:16);ctx.fillStyle=color('--text');ctx.fillRect(x-1,y-(rope?48:8),2,rope?96:16);if(!reduced.matches){m.dashes.forEach(d=>{const age=time-d.t,pos=d.side>0?age*.16:w-age*.16;if(pos<0||pos>w||d.side>0&&pos>x||d.side<0&&pos<x)return;ctx.globalAlpha=clamp(1-age/2000,0,.9);ctx.fillStyle=d.side>0?violet:ink;ctx.fillRect(pos,y-1,d.size,2);});ctx.globalAlpha=1;if(Math.abs(m.delta)>.1){ctx.fillStyle=ink;for(let k=1;k<=3;k++)ctx.fillRect(x+(m.delta>0?1:-1)*k*5,y+8,1,4);}}if(rope){ctx.fillStyle=text;ctx.font='11px system-ui';ctx.textAlign='center';[0,.25,.5,.75,1].forEach(t=>{const label=m.scalar?(Number(m.lowerBound)+t*(Number(m.upperBound)-Number(m.lowerBound))).toFixed(0):String(t*100);ctx.fillText(label,clamp(t*w,12,w-12),h-2);});if(!reduced.matches)m.history.slice(-24).forEach((v,i)=>{ctx.globalAlpha=.6*Math.exp(-(24-i)/8);ctx.fillRect(v*w,4,1,8);});ctx.globalAlpha=1;}if(mini&&activeMarket){const q=quote(activeMarket,chosen,amount);ctx.strokeStyle=color('--violet-text');ctx.lineWidth=2;ctx.strokeRect(clamp(q.after*w,4,w-4)-4,4,8,h-8);}}
function drawHistory(ctx,m,w,h,color){const pad=32,gutter=64,pw=w-pad-gutter,ph=h-48;ctx.font='11px system-ui';ctx.fillStyle=color('--text-2');ctx.textAlign='left';[0,25,50,75,100].forEach(n=>{const y=16+ph*(1-n/100);ctx.fillText(n+'',0,y+4);ctx.fillStyle=color('--nested');ctx.fillRect(pad,y,pw,1);ctx.fillStyle=color('--text-2');});const count=range==='1D'?16:range==='1W'?32:range==='1M'?48:64,points=m.history.slice(-count);ctx.strokeStyle=color('--violet');ctx.lineWidth=2;ctx.beginPath();points.forEach((p,i)=>{const x=pad+i/(points.length-1)*pw,y=16+(1-p)*ph;if(i){ctx.lineTo(x,16+(1-points[i-1])*ph);ctx.lineTo(x,y);}else ctx.moveTo(x,y);});ctx.stroke();ctx.fillStyle=color('--violet-text');ctx.fillText((points.at(-1)*100).toFixed(1)+'%',w-gutter+8,clamp(16+(1-points.at(-1))*ph,20,h-32));ctx.fillStyle=color('--text-2');ctx.fillText(range==='1D'?'24h ago':range==='1W'?'7d ago':'Illustrative history',pad,h-8);ctx.fillText('Now',w-gutter-24,h-8);if(m.cross!==undefined){const i=clamp(m.cross,0,points.length-1),x=pad+i/(points.length-1)*pw;ctx.strokeStyle=color('--text-2');ctx.beginPath();ctx.moveTo(x,16);ctx.lineTo(x,ph+16);ctx.stroke();ctx.fillStyle=color('--card');ctx.fillRect(clamp(x-32,pad,w-144),24,80,32);ctx.fillStyle=color('--text');ctx.fillText((points[i]*100).toFixed(2)+'%',clamp(x-24,pad+8,w-136),45);}}
function bindHistory(){const c=$('.history');c.onpointermove=e=>{const r=c.getBoundingClientRect();activeMarket.cross=Math.round(clamp((e.clientX-r.left-32)/(r.width-96),0,1)*(range==='1D'?15:range==='1W'?31:range==='1M'?47:63));};c.onpointerleave=()=>{delete activeMarket.cross;};c.onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();activeMarket.cross=clamp((activeMarket.cross||0)+(e.key==='ArrowRight'?1:-1),0,63);}};}
function animate(time){const dt=Math.min((time-lastFrame)/1000,.05)||.016;lastFrame=time;if(!document.hidden){const onScreen=[...visible],ids=[...new Set(onScreen.map(c=>c.dataset.market))].slice(0,25);for(const id of ids){const m=markets.find(m=>m.id===id);if(!m||!m.priced)continue;m.next-=dt;if(m.next<=0&&!reduced.matches){const old=m.p,L=Math.max(m.liquidityUSD,50),normal=Math.sqrt(-2*Math.log(Math.max(m.random(),.0001)))*Math.cos(2*Math.PI*m.random()),step=reduced.matches?5:1;m.x+=.002*(logit(m.base)-m.x)*step+.35/Math.sqrt(L/1000+1)*Math.sqrt(step)*normal;m.p=sigmoid(m.x);m.delta=(m.p-old)*100;m.history.push(m.p);m.history.shift();m.next=reduced.matches?5:-Math.log(Math.max(m.random(),.001))/clamp(m.volumeUSD/2e5,.03,.4);m.dashes.push({t:time,side:Math.sign(m.delta),size:clamp(4+2*Math.log10(Math.exp(Math.log(L/40)+normal*.8)),4,12)});m.dashes=m.dashes.filter(d=>time-d.t<2500).slice(-6);$$(`[data-price="${m.id}"]`).forEach(el=>{el.textContent=(m.p*100).toFixed(1)+'%';el.classList.remove('roll');requestAnimationFrame(()=>{if(!document.hidden)el.classList.add('roll');});});$$(`[data-cents="${m.id}"]`).forEach(el=>el.textContent=(m.p*100).toFixed(1)+'¢');$$(`[data-delta="${m.id}"]`).forEach(el=>{el.textContent=`${m.delta>=0?'▲':'▼'}${Math.abs(m.delta).toFixed(1)}`;el.classList.toggle('negative',m.delta<0);});if(activeMarket===m)updateQuote();m.updatedAt=Date.now();if(agent){refreshMachine(m);const el=$(`.market-card[data-id="${m.id}"] .agent-line`);if(el)el.textContent=agentLine(m);}}if(reduced.matches){m.display=m.p;m.velocity=0;}else{const acceleration=144*(m.p-m.display)-24*m.velocity;m.velocity+=acceleration*dt;m.display+=m.velocity*dt;}}onScreen.forEach(c=>{const m=markets.find(m=>m.id===c.dataset.market);if(m)draw(c,m,time,dt);});}refreshConsole();requestAnimationFrame(animate);}
function pools(m){showDialog('Pool balances',`<p>Liquidity ${money(m.liquidityUSD)} · Open interest ${money(m.openInterestUSD)}</p>${(m.poolBalance||[]).filter(Boolean).map(p=>`<div class="pool-row">${Number(p.token0.balance).toFixed(4)} ${esc(p.token0.symbol)}<br>${Number(p.token1.balance).toFixed(4)} ${esc(p.token1.symbol)}</div>`).join('')||'<p>No pool balances in sample.</p>'}`);}
function route(){closePopover(); $('.filter-panel')?.remove();if(dialog.open)dialog.close();observer.disconnect();visible.clear();const path=location.hash.slice(1).split('?')[0]||'/';if(path.startsWith('/market/')){const m=markets.find(m=>m.id===decodeURIComponent(path.split('/')[2]));if(m)marketPage(m);else{app.innerHTML='<div class="empty">Market not included in sample. <a href="#/">All markets →</a></div>';activeMarket=null;}}else if(path==='/leaderboard'){activeMarket=null;app.innerHTML='<div class="breadcrumb"><a href="#/">Home</a> / Leaderboard</div><section class="panel"><h1>Leaderboard</h1><p class="muted">Ranking data is not included in this market sample.</p><a href="#/">Explore markets →</a></section>';}else if(path==='/create-market'){activeMarket=null;app.innerHTML='<div class="breadcrumb"><a href="#/">Home</a> / Create Market</div><section class="panel"><h1>Create Market</h1><p>Market creation is unavailable in this standalone preview.</p><a href="https://app.seer.pm/#/create-market" target="_blank" rel="noreferrer">Create on Seer ↗</a></section>';}else home();$$('header nav a').forEach(a=>{const current=a.hash===(location.hash||'#/');a.classList.toggle('active',current);if(current)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});syncAgent();window.scrollTo(0,0);}
async function copy(value){try{await navigator.clipboard.writeText(value);toast('Copied');}catch{showDialog('Copy',`<label>Select and copy</label><textarea style="width:100%;height:160px">${esc(value)}</textarea>`);$('textarea',dialog).select();}}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b){const card=e.target.closest('.market-card');if(card&&!e.target.closest('a,button,input,select,.drawer'))location.hash='/market/'+card.dataset.id;return;}const action=b.dataset.action,id=b.dataset.id,m=markets.find(x=>x.id===id)||activeMarket,index=Number(b.dataset.index);switch(action){case'share':copy(location.href);break;case'chart-tab':chartTab=b.dataset.tab;$$('.chart-tabs [data-tab]').forEach(x=>x.classList.toggle('selected',x===b));renderChart();break;case'trade-side':tradeSide=b.dataset.side;$$('.trade-side button').forEach(x=>x.classList.toggle('selected',x===b));$('#amount').setAttribute('aria-label',tradeSide==='Sell'?'Shares to sell':'You pay amount');$('.amount-label span').textContent=tradeSide==='Sell'?'Shares to sell':'You pay · '+collateral(m);updateQuote();break;case'agent-console':consoleOpen=!consoleOpen;syncAgent();break;case'agent-layout':agentLayout=b.dataset.layout;renderGrid();break;case'query-format':queryFormat=b.dataset.format;syncAgent();break;case'copy-query':copy(queryText());break;case'machine-copy':copy(JSON.stringify(machine(m),null,2));break;case'theme':{const light=document.documentElement.dataset.theme!=='light';document.documentElement.dataset.theme=light?'light':'dark';localStorage.setItem('seam.theme',light?'light':'dark');$('#theme').setAttribute('aria-label',`Switch to ${light?'dark':'light'} mode`);break;}case'dismiss':$('.beta').remove();localStorage.setItem('seam.beta','off');break;case'filter-popover':openFilters(b.dataset.key,b);break;case'category':filters.category=b.dataset.value;writeURL();renderGrid();break;case'view-all':e.preventDefault();$('.toolbar').scrollIntoView({behavior:reduced.matches?'instant':'smooth'});break;case'close-filters':$('.filter-panel')?.remove();break;case'remove-filter':filters[b.dataset.key]=defaults[b.dataset.key];writeURL();renderGrid();break;case'reset':filters={...defaults};collections=false;$('#search').value='';writeURL();renderGrid();break;case'hero':heroIndex=index;renderHero();break;case'pin':b.closest('.market-card').classList.toggle('pinned');break;case'star':{saved.has(m.id)?saved.delete(m.id):saved.add(m.id);localStorage.setItem('seam.saved',JSON.stringify([...saved]));b.textContent=saved.has(m.id)?'★':'☆';b.classList.toggle('saved',saved.has(m.id));b.setAttribute('aria-label',saved.has(m.id)?'Remove saved market':'Save market');toast(saved.has(m.id)?'Saved to My collections':'Removed from My collections');break;}case'collections':collections=!collections;if(activeMarket)location.hash='#/';else home();break;case'quick':quick(m,index);break;case'quick-side':quickIndex=index;$$('.segmented button',dialog).forEach(el=>el.classList.toggle('selected',Number(el.dataset.index)===index));updateQuick();break;case'quick-confirm':if(!connected)connect();else toast(Number($('#quick-amount').value)>0?'Not enough balance. · Prototype: signing disabled':'Enter an amount');break;case'connect':connect();break;case'disconnect':connected=false;$('#wallet').textContent='Connect';dialog.close();updateQuote();break;case'close-dialog':dialog.close();break;case'human':case'agent':agent=action==='agent';localStorage.setItem('seam.agent',agent);activeMarket?marketPage(activeMarket):home();break;case'outcome':chosen=index;if($('#outcome-select'))$('#outcome-select').value=chosen;$$('.outcome').forEach(el=>el.classList.toggle('selected',Number($('button',el)?.dataset.index)===index));$$('#ticket-sides button').forEach(el=>el.classList.toggle('selected',Number(el.dataset.index)===index));updateQuote();break;case'all-outcomes':$('#outcomes').innerHTML=outcomes(m,true);b.remove();break;case'trade':$('#ticket').classList.add('mobile-open');$('#ticket').setAttribute('role','dialog');$('#ticket').setAttribute('aria-label','Trade ticket');$('#ticket .ticket-head .icon').focus();break;case'close-trade':closeTicket();break;case'max':amount=0;$('#amount').value=0;updateQuote();toast('Available balance: 0 '+collateral(m));break;case'trade-confirm':if(!connected)connect();else if(tradeSide==='Sell')toast('Not enough share balance.');else toast(amount>0?'Not enough balance. · Prototype: signing disabled':'Enter an amount');break;case'reject':dialog.close();toast('Prototype: signing disabled');break;case'tab':renderTab(b.dataset.tab);break;case'copy':copy(b.dataset.value);break;case'copy-signal':copy(JSON.stringify(signal(m),null,2));break;case'pools':pools(m);break;case'outcome-menu':showDialog(esc(m.outcomes[index]),`<div class="menu-list"><button data-action="liquidity">Add Liquidity</button><button data-action="pools" data-id="${m.id}">View pool details</button><button data-action="conditional-create">New conditional market</button></div>`);break;case'liquidity':showDialog('Add Liquidity',`<p>Farming Rewards: ${m.incentive>0?'Available':'None in sample'}</p><p>Liquidity: ${money(m.liquidityUSD)}</p><button class="primary" data-action="reject">${connected?'Prototype: signing disabled':'Connect'}</button>`);break;case'create':if(dialog.open)dialog.close();location.hash='/create-market';break;case'conditional-create':showDialog('Create New Market','<p>Market creation is unavailable in this standalone preview.</p><button class="primary" data-action="close-dialog">Return</button>');break;case'answer':showDialog('Answer on Reality.eth!',`<p>${m.hasAnswers?'An answer has been submitted.':'Not answered yet'}</p><label>Choose an answer</label><select>${m.outcomes.map(o=>`<option>${esc(o)}</option>`).join('')}</select><label class="filter-option"><input type="checkbox">Mark this question invalid</label><p>Bond: ${Number(m.questions?.[0]?.min_bond||0)/1e18} xDAI</p><button class="primary" data-action="reject">Answer</button><button data-action="close-dialog">Return</button>`);break;case'verify':showDialog('Verification',`<p>${esc(m.verification?.status||'not_verified')}</p><p>Item ${esc(m.verification?.itemID||'Not available')}</p><button class="primary" data-action="reject">Verify it</button>`);break;case'range':if(b.dataset.range==='Custom'){showDialog('Custom range',`<label>History window</label><select id="custom-range"><option>1D</option><option>1W</option><option>1M</option><option>All</option></select><button class="primary" data-action="save-range">Save</button><button data-action="close-dialog">Cancel</button>`);}else{range=b.dataset.range;$$('.chart-tools button').forEach(el=>el.classList.toggle('selected',el===b));if(activeMarket)renderChart();}break;case'save-range':range=$('#custom-range').value;$$('.chart-tools button').forEach(el=>el.classList.toggle('selected',el.dataset.range===range));dialog.close();if(activeMarket)renderChart();break;case'export':{const blob=new Blob(['point,probability,source\n'+m.history.map((p,i)=>`${i},${p},SIM`).join('\n')],{type:'text/csv'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`seer-${m.id}-SIM.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Illustrative history exported');break;}case'slippage':showDialog('Max slippage','<label>Slippage %</label><input id="slippage" type="number" min="0.1" max="50" step="0.1" value="1"><button class="primary" data-action="save-slippage">Save</button>');break;case'save-slippage':{const value=clamp(Number($('#slippage').value)||1,.1,50);$('[data-action=slippage]').textContent=`Max slippage ${value}% ⚙`;dialog.close();break;}case'order-type':toast('Market order · estimated price impact');break;case'more':showDialog('More',`<div class="menu-list">${['Mint','Merge','Redeem'].map(s=>`<button data-action="operation" data-label="${s}">${s}</button>`).join('')}</div>`);break;case'operation':showDialog(b.dataset.label,`<p>${b.dataset.label} · ${collateral(m)} · Balance 0</p><label>Amount</label><input type="number" min="0" value="0"><button class="primary" data-action="reject">${connected?'Not enough balance.':'Connect'}</button>`);break;case'bridge':showDialog('Bridge tokens','<p>Bridge transactions are unavailable in this standalone preview.</p><button class="primary" data-action="close-dialog">Return</button>');break;case'help':showDialog('Read the seam','<p>The filled side is the leading outcome. The hatched side is the rest. The seam follows simulated price changes around real odds.</p><p>Open a market to inspect who asked, what is priced, and how much money could move its signal.</p><p>Drag the ticket grip to estimate the cost of moving a price. All signing is disabled.</p><button class="primary" data-action="close-dialog">Explore markets</button>');break;case'policies':showDialog('Policies','<div class="menu-list"><button data-action="policy" data-label="Market resolution">Market resolution</button><button data-action="policy" data-label="Verification policy">Verification policy</button></div>');break;case'policy':showDialog(b.dataset.label,`<p>${b.dataset.label==='Market resolution'?'Reality.eth answers determine payouts. Disputed answers go to the market’s arbitrator.':'Verification is derived from the Kleros item status in the real market record.'}</p><button class="primary" data-action="close-dialog">Return</button>`);break;case'apps':openApps(b);break;case'menu':showDialog('Seer','<div class="menu-list"><a href="#/" data-action="close-dialog">Markets</a><a href="#/leaderboard" data-action="close-dialog">Leaderboard</a><button data-action="create">Create Market</button><button data-action="policies">Policies</button><button data-action="apps">App</button><button data-action="connect">Connect / Account</button><button data-action="agent">Agent view</button></div>');break;case'account-item':showDialog(b.dataset.label,`<p>${esc(b.dataset.label)} is unavailable in this standalone preview.</p><button class="primary" data-action="close-dialog">Return</button>`);break;}});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closePopover();$('.filter-panel')?.remove();closeTicket();consoleOpen=false;syncAgent();}if(e.target.matches('input,select,textarea'))return;if(e.key==='/'){e.preventDefault();$('#search').focus();}if(e.key.toLowerCase()==='a'&&!dialog.open){agent=!agent;localStorage.setItem('seam.agent',agent);activeMarket?marketPage(activeMarket):home();}});
$('#search').addEventListener('input',()=>{writeURL();if(activeMarket||!$('#grid'))location.hash='#/';else renderGrid();});
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#/"]');if(!a||e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;e.preventDefault();e.stopImmediatePropagation();const target=a.getAttribute('href');if(location.hash===target)route();else location.hash=target;},true);
window.addEventListener('hashchange',route);
setInterval(()=>{if(!document.hidden&&!reduced.matches&&!heroPaused&&!dialog.open&&$('#hero')&&!$('.filter-panel')){heroIndex=(heroIndex+1)%5;renderHero();}},8000);
if(localStorage.getItem('seam.theme')==='light'){document.documentElement.dataset.theme='light';$('#theme').setAttribute('aria-label','Switch to dark mode');}
if(localStorage.getItem('seam.beta')==='off')$('.beta').remove();
try{const response=await fetch('../data/markets.json');if(!response.ok)throw new Error(`Market file: ${response.status}`);const data=await response.json();markets=data.markets.map(adapt);readURL();route();requestAnimationFrame(animate);}catch(error){app.innerHTML=`<div class="empty">${esc(error.message)}<p>The shared market file could not be loaded.</p><button data-action="reload">Retry</button></div>`;$('[data-action=reload]').onclick=()=>location.reload();}


document.addEventListener('click',e=>{if(!e.target.closest('.filter-anchor,.app-popover,[data-action=apps],.search'))closePopover();});
function recent(){try{const values=JSON.parse(localStorage.getItem('seam.recent')||'[]');return Array.isArray(values)?values.filter(v=>typeof v==='string'):[];}catch{return [];}}
$('#search').addEventListener('focus',()=>{closePopover();const values=recent();if(!values.length)return;const pop=document.createElement('div');pop.className='recent-searches';pop.innerHTML='<span>Recent searches</span>'+values.map(v=>`<button>${esc(v)}</button>`).join('');$('.search').append(pop);pop.onclick=e=>{const b=e.target.closest('button');if(b){$('#search').value=b.textContent;writeURL();closePopover();if(!$('#grid'))location.hash='/';else renderGrid();}};});
$('#search').addEventListener('change',()=>{const q=$('#search').value.trim();if(q)localStorage.setItem('seam.recent',JSON.stringify([q,...recent().filter(v=>v!==q)].slice(0,5)));});

function machine(m){return {market_id:m.id,outcome_token_ids:m.wrappedTokens,implied_probability:m.priced?Number(m.p.toFixed(3)):null,bid_ask_spread:null,depth_1pct_usd:m.priced?Number((.25*Math.max(m.liquidityUSD,50)*Math.abs(logit(clamp(m.p+.01,.001,.999))-logit(m.p))).toFixed(2)):null,last_update:m.updatedAt?new Date(m.updatedAt).toISOString():null,resolution_source:'Reality.eth',source:'fixture + simulated ticks'};}
function machineStrip(m){const data=machine(m);return `<div class="machine-strip" data-machine="${m.id}"><div><span>Market id</span><button data-action="copy" data-value="${m.id}" aria-label="Copy market id ${m.id}">${short(m.id)} ⧉</button><button data-action="machine-copy" data-id="${m.id}">API</button></div><dl><div><dt>Implied p</dt><dd data-machine-p>${m.priced?m.p.toFixed(3):'N/A'}</dd></div><div><dt>Bid/ask spread</dt><dd>N/A</dd></div><div><dt>Depth 1%</dt><dd>${data.depth_1pct_usd===null?'N/A':money(data.depth_1pct_usd)} SIM</dd></div><div><dt>Update age</dt><dd data-machine-age>${m.updatedAt?'0s SIM':'Snapshot'}</dd></div><div><dt>Resolution</dt><dd>Reality.eth</dd></div></dl><details><summary>Outcome token ids (${m.wrappedTokens.length})</summary>${m.wrappedTokens.map((id,i)=>`<div class="token-id"><span>${esc(m.outcomes[i])}</span><button data-action="copy" data-value="${id}" aria-label="Copy token id ${id}">${esc(id)}</button></div>`).join('')}</details></div>`;}
function queryText(){const query={source:'../data/markets.json',operation:'local filter and sort',filters:{...filters,marketName:$('#search').value,collection:collections?[...saved]:null},limit:3};return queryFormat==='JSON'?JSON.stringify(query,null,2):`# Local query model, not a hosted GraphQL endpoint\nquery Markets($filters: MarketFilters!, $limit: Int!) {\n  markets(filters: $filters, limit: $limit) {\n    market_id outcome_token_ids implied_probability\n    bid_ask_spread depth_1pct_usd last_update resolution_source\n  }\n}\n# Variables\n${JSON.stringify({filters:query.filters,limit:3},null,2)}`;}
function syncAgent(){document.body.classList.toggle('agent-mode',agent);$('#agent-tools')?.remove();$('#agent-console')?.remove();$('#agent-scanline')?.remove();const grid=$('#grid');if(grid){grid.classList.toggle('agent-rows',agent);grid.classList.toggle('agent-table',agent&&agentLayout==='table');}if(!agent)return;const tools=document.createElement('section');tools.id='agent-tools';tools.className='agent-tools';tools.innerHTML=`<div><strong>Agent view</strong><p>Read and copy the current market signals.</p></div><div class="layout-options"><button ${grid?'':'hidden'} data-action="agent-layout" data-layout="rows" aria-pressed="${agentLayout==='rows'}">Rows</button><button ${grid?'':'hidden'} data-action="agent-layout" data-layout="table" aria-pressed="${agentLayout==='table'}">Table</button><button data-action="agent-console" aria-expanded="${consoleOpen}">Agent console ${consoleOpen?'×':'›'}</button></div>`;($('#grid')||$('.market-layout')||app.firstElementChild)?.before(tools);const scan=document.createElement('div');scan.id='agent-scanline';scan.setAttribute('aria-hidden','true');document.body.append(scan);if(consoleOpen){const drawer=document.createElement('aside');drawer.id='agent-console';drawer.setAttribute('aria-label','Agent console');drawer.innerHTML=`<div class="console-heading"><h2>Agent console</h2><button data-action="agent-console" aria-label="Close Agent console">×</button></div><p>Current filters · local sample</p><div class="tabs"><button data-action="query-format" data-format="JSON" aria-pressed="${queryFormat==='JSON'}">JSON</button><button data-action="query-format" data-format="GraphQL" aria-pressed="${queryFormat==='GraphQL'}">GraphQL</button><button data-action="copy-query">Copy query</button></div><pre id="agent-query"></pre><h3>Live response · first 3</h3><p>Snapshot odds with simulated updates</p><pre id="agent-response"></pre>`;document.body.append(drawer);refreshConsole();}}
function refreshMachine(m){const strip=$(`[data-machine="${m.id}"]`);if(strip){$('[data-machine-p]',strip).textContent=m.p.toFixed(3);strip.classList.remove('updated');requestAnimationFrame(()=>strip.classList.add('updated'));}}
function refreshConsole(){if(!agent)return;$$('[data-machine-age]').forEach(el=>{const m=markets.find(x=>x.id===el.closest('[data-machine]').dataset.machine);el.textContent=m?.updatedAt?Math.floor((Date.now()-m.updatedAt)/1000)+'s SIM':'Snapshot';});if(!$('#agent-response'))return;const response=JSON.stringify(selectedMarkets().slice(0,3).map(machine),null,2);if($('#agent-response').textContent!==response)$('#agent-response').textContent=response;const query=queryText();if($('#agent-query').textContent!==query)$('#agent-query').textContent=query;}

function closeTicket(){const ticket=$('#ticket');if(!ticket?.classList.contains('mobile-open'))return;ticket.classList.remove('mobile-open');ticket.removeAttribute('role');ticket.removeAttribute('aria-label');$('.mobile-trade')?.focus();}
document.addEventListener('keydown',e=>{const ticket=$('#ticket.mobile-open');if(!ticket||e.key!=='Tab')return;const controls=$$('button:not(:disabled),input:not(:disabled),select:not(:disabled),a[href]',ticket).filter(el=>el.getClientRects().length);const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}});
